/* E12-SD 44.1 kHz render (e12sd_render_block_44k1), hand-written SHARC+.
 * Generated by gen_e12a.py.
 *
 * Bit-exact replacement for the translated render of the original OS 1.63
 * DSP56300 code at P:$103b46-$103c7a, shared by E12-SD, SH, BC, RC and BR:
 * the group-A code with a second, crossfaded sample stream (Y23, Y24, Yb)
 * and fixed biquad numerators (model: e12ht_model.py, variant 'b'). It
 * keeps the translated voice layout and the shared scratch contract (E12
 * maps 256 scratch words):
 * every word of voice state, x/y scratch, y:$20 history and the 44.1 kHz
 * block ends as the original leaves it.
 *
 *  1. Pitch step S = clamp(8*(Y1 + floor(2*lim(2*Y15*Y8)*Y1/2^24)), 0, 4.0);
 *     the position (from Y11) advances by S per sample in one 32-bit
 *     register (it stays below 2^31): x:$a0+k = whole part, y:$a0+k =
 *     coefficient address $147400 + (floor(sx(frac) / 2^14) & ~3). Y10:Y11
 *     loops to Y13 at Y1c = lim(2*Y7*Y13).
 *  2. Loop-point rebasing (Y1e, Y1f, Ya, Ye, Y6): x1 = lim(off + 2*Y13*Y6),
 *     the last offsets -= x1.
 *  3. 68 source words from Y12 + pos/2, two 12-bit samples a word, into
 *     x:0..$87 (odd positions start one sample later, the first at x:$87).
 *  4. Envelope y:k (Y15 *= Y3).
 *  5. 4-tap interpolation (source-word coefficients) times the envelope into
 *     x:$c8+k.
 *  6. Biquad (E12 tables $103c7b/$103cfb) with a full-precision accumulator
 *     (Y18:Y1b) in MRF; l: stores to x:/y:$c6+n; block = lim(acc).
 *
 * After a loop-point rebase the original's offsets can point anywhere (they
 * are typically negative): those taps read as parallel moves do, scratch,
 * source words, or 0 at and above $200000, on a slow path.
 *
 * Declines (calls the reference render) when the sample words or a
 * coefficient table address fall outside the source words, or a rebased tap
 * would read boot X memory or the fault window.
 *
 * Calling convention as the translated renders: R4 = voice, R8 = sine.
 * @SRC@ = byte address of source word 0 (immutable source base - 0x80000).
 * @TMP@ = a 256-word scratch block owned by the hand-written renders.
 */
.EXTERN md_shared_scratch_x.;
.EXTERN md_shared_scratch_y.;
.EXTERN md_shared_y20.;
.EXTERN e12sd_render_block_44k1_c.;
.SECTION/SW seg_swco;
.GLOBAL e12sd_render_block_44k1.;
e12sd_render_block_44k1.:
    I7=MODIFY (I7,-0x34)(NW);
    DM (-3,I6) = R8;
    DM (-4,I6) = R9;
    DM (-5,I6) = R10;
    DM (-6,I6) = R11;
    DM (-7,I6) = R12;
    DM (-8,I6) = R13;
    DM (-9,I6) = R14;
    DM (-10,I6) = R15;
    R0 = I0;
    DM (-11,I6) = R0;
    R0 = I1;
    DM (-12,I6) = R0;
    R0 = I2;
    DM (-13,I6) = R0;
    R0 = I3;
    DM (-14,I6) = R0;
    R0 = I4;
    DM (-15,I6) = R0;
    R0 = I5;
    DM (-16,I6) = R0;
    R0 = M4;
    DM (-17,I6) = R0;
    R0 = M0;
    DM (-18,I6) = R0;
    R0 = M1;
    DM (-19,I6) = R0;
    R0 = M2;
    DM (-20,I6) = R0;
    R0 = M3;
    DM (-21,I6) = R0;
    R0 = MR0F;
    DM (-22,I6) = R0;
    R0 = MR1F;
    DM (-23,I6) = R0;
    R0 = MR2F;
    DM (-24,I6) = R0;
    DM (-28,I6) = R8;
    R0 = L0;
    DM (-46,I6) = R0;
    R0 = L1;
    DM (-47,I6) = R0;
    R0 = L2;
    DM (-48,I6) = R0;
    R0 = L3;
    DM (-49,I6) = R0;
    R0 = L4;
    DM (-50,I6) = R0;
    R0 = L5;
    DM (-51,I6) = R0;
    R0 = 0;
    L0 = R0;
    L1 = R0;
    L2 = R0;
    L3 = R0;
    L4 = R0;
    L5 = R0;
    I0 = R4;
    R14 = 0x7FFFFF;
    R15 = 0xFF800000;
    R13 = @SRC@;
/* ---- guards (no writes but @TMP@) ----------------------------------------- */
    I2 = @TMP@;
    R0 = DM (0x13,I0);
    R1 = DM (7,I0);
    R1 = LSHIFT R1 BY 8;
    R2 = R0 * R1 (SSF);
    R2 = MIN(R2,R14);
    DM (8,I2) = R2;                 /* Y1c = lim(2*Y7*Y13) */
    R0 = DM (0x15,I0);
    R1 = DM (8,I0);
    R1 = LSHIFT R1 BY 8;
    R2 = R0 * R1 (SSF);
    R2 = MIN(R2,R14);                    /* lim(2*Y15*Y8) */
    R1 = DM (1,I0);
    R3 = LSHIFT R1 BY 8;
    R2 = R2 * R3 (SSF);                  /* floor(2*x1*Y1 / 2^24) */
    R1 = FEXT R1 BY 0:24;
    R2 = R2 + R1;
    R2 = LSHIFT R2 BY 3;
    R3 = 0x4000000;
    R2 = MIN(R2,R3);
    R3 = 0;
    R2 = MAX(R2,R3);
    DM (9,I2) = R2;               /* step */
    R4 = DM (0x11,I0);
    R4 = FEXT R4 BY 0:24;                /* position frac (whole part 0) */
    R0 = DM (0x10,I0);
    DM (13,I2) = R0;                /* sample position = Y10 */
    /* S2 mode: 0 counting, 1 nothing, 2 rebase */
    R0 = DM (0x1E,I0);
    R1 = 0x20;
    R0 = R0 + R1;
    DM (15,I2) = R0;
    R1 = DM (0xA,I0);
    R5 = 0;
    COMP (R0,R1);
    IF LT JUMP .L_g_mode;
    R5 = 1;
    R6 = DM (0x1F,I0);
    R7 = 1;
    R6 = R6 + R7;
    R7 = DM (0xE,I0);
    COMP (R6,R7);
    IF GE JUMP .L_g_mode;
    R5 = 2;
    R0 = R0 - R1;
    R1 = 0x1F;
    R0 = R0 AND R1;                      /* cnt */
    DM (11,I2) = R0;
    /* offsets off(j) = (frac + j*step) >> 24, j = 0..31, to @TMP@[32+j] */
    I3 = @TMP@;
    I3=MODIFY (I3,0x20)(NW);
    R7 = PASS R4;
    LCNTR = 0x20 , DO (PC,.L_g_off_end)UNTIL LCE;
    R9 = LSHIFT R7 BY -24;
    R7 = R7 + R2;
.L_g_off_end:
    DM (I3,M6) = R9;
    R6 = 31;
    R6 = R6 - R0;                        /* j0 */
    M4 = R6;
    I3 = @TMP@;
    I3=MODIFY (I3,0x20)(NW);
    R7 = DM (M4,I3);                     /* off(j0) */
    R8 = DM (0x13,I0);
    R9 = DM (6,I0);
    R9 = LSHIFT R9 BY 8;
    R8 = R8 * R9 (SSF);
    R8 = R8 + R7;
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);                    /* x1 */
    DM (12,I2) = R8;
    DM (13,I2) = R8;
    R0 = PASS R0;
    IF EQ JUMP .L_g_mode;
    /* every tap of the rebased offsets used (j = max(1, j0) .. 30) reads
     * scratch, source words or 0, never boot X or the fault window */
    R9 = 1;
    R6 = MAX(R6,R9);
    R0 = 31;
    R0 = R0 - R6;                        /* offsets to check */
    R6 = LSHIFT R6 BY 2;
    R1 = I3;
    R6 = R6 + R1;
    I3 = R6;
    R10 = 0;                             /* bad taps */
    R9 = 0x100;
    R3 = 0x1FF00;
    LCNTR = R0 , DO (PC,.L_g_tap_end)UNTIL LCE;
    R7 = DM (I3,M6);
    R7 = R7 - R8;
    R7 = MIN(R7,R14);
    R7 = MAX(R7,R15);
    R1 = FEXT R7 BY 0:24;
    R1 = R1 - R9;
    COMPU (R1,R3);
    IF LT R10 = R10 + 1;
    R1 = 1;
    R7 = R7 + R1;
    R1 = FEXT R7 BY 0:24;
    R1 = R1 - R9;
    COMPU (R1,R3);
    IF LT R10 = R10 + 1;
    R1 = 1;
    R7 = R7 + R1;
    R1 = FEXT R7 BY 0:24;
    R1 = R1 - R9;
    COMPU (R1,R3);
    IF LT R10 = R10 + 1;
    R1 = 1;
    R7 = R7 + R1;
    R1 = FEXT R7 BY 0:24;
    R1 = R1 - R9;
    COMPU (R1,R3);
    IF LT R10 = R10 + 1;
    NOP;
.L_g_tap_end:
    NOP;
    R10 = PASS R10;
    IF NE JUMP .L_decline;
.L_g_mode:
    DM (10,I2) = R5;
    /* the 68 sample words */
    R0 = DM (13,I2);
    R1 = -1;
    R0 = ASHIFT R0 BY R1;
    R1 = DM (0x12,I0);
    R0 = R0 + R1;
    R0 = FEXT R0 BY 0:24;
    DM (14,I2) = R0;
    R1 = 0x20000;
    R0 = R0 - R1;
    R1 = 0x1DFFBC;
    COMPU (R0,R1);
    IF GT JUMP .L_decline;
    /* the second stream (when the position is below Y23) */
    R5 = 0;
    R0 = DM (13,I2);
    R1 = DM (0x23,I0);
    COMP (R0,R1);
    IF GE JUMP .L_g_s2;
    R5 = 1;
    R1 = -1;
    R0 = ASHIFT R0 BY R1;
    R1 = DM (0x24,I0);
    R0 = R0 + R1;
    R0 = FEXT R0 BY 0:24;
    DM (17,I2) = R0;
    R1 = 0x20000;
    R0 = R0 - R1;
    R1 = 0x1DFFBC;
    COMPU (R0,R1);
    IF GT JUMP .L_decline;
.L_g_s2:
    DM (16,I2) = R5;
    /* biquad coefficients (E12 tables) */
    R7 = -7;
    R6 = -8;
    R9 = DM (5,I0);
    R10 = DM (4,I0);
    NOP;
    NOP;
    /* (inlined .L_coef) */
    R1 = 0x103C7B;
    R1 = R1 + R10;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R4 = DM (0,I4);
    R1 = 0x103CFB;
    R1 = R1 + R10;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R5 = DM (0,I4);
    R4 = R4 + R9;
    R5 = R5 + R9;
    R1 = 0x140900;
    R1 = R1 + R4;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R11 = DM (0,I4);
    R1 = 0x141900;
    R1 = R1 + R5;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R12 = DM (0,I4);
    R11 = LSHIFT R11 BY 8;
    R12 = LSHIFT R12 BY 8;
    JUMP .L_coef_ret_i1 (DB);
    R0 = R0 - R0;
    NOP;
.L_coef_bad_i1:
    JUMP .L_coef_ret_i1 (DB);
    R0 = -1;
    NOP;
.L_coef_ret_i1:
    R0 = PASS R0;
    IF NE JUMP .L_decline;
    I2 = @TMP@;
    /* R11 = xx << 8, R12 = yy << 8 */
    R1 = ASHIFT R11 BY R7;               /* 2*xx */
    R2 = R12 * R1 (SSF);                 /* floor(4*xx*yy / 2^24) */
    R3 = 0x400000;
    R2 = R2 - R3;
    R2 = MIN(R2,R14);
    R2 = MAX(R2,R15);
    DM (1,I2) = R2;                      /* g2c = lim(g2 - 1/2) (b, rs: lim(asl G - 1/2)) */
    R3 = ASHIFT R12 BY R6;               /* yy */
    R4 = 0;
    MR1F = R4;
    MR0F = R4;                           /* MR = 0 */
    MRF = MRF - R12 * R3 (SSF);
    MRF = MRF - R12 * R3 (SSF);
    R4 = MR1F;
    R4 = MAX(R4,R15);
    DM (0,I2) = R4;                      /* c2 = lim(asl C) */
    R1 = 0x400000;
    DM (2,I2) = R1;                      /* b0 = 1/2 */
    DM (3,I2) = R15;                     /* b1 = -1 */
    JUMP .L_body;

    /* R9 = sel, R10 = idx: R11 = x1 << 8 = x:(sel + x:($140000+idx) + $140900),
     * R12 = y1 << 8 = x:(sel + x:($140080+idx) + $141900); R0 = 0, or -1 when
     * an address is outside the source words */

/* ---- body ----------------------------------------------------------------- */
.L_body:
    /* y:$20 history: y:$20 = y20 at entry, y20 = u24(y:$20) at exit */
    I1 = md_shared_y20.;
    R1 = DM (0,I1);
    R1 = FEXT R1 BY 0:24;
    DM (0,I1) = R1;
    R1 = LSHIFT R1 BY 8;
    R6 = -8;
    R1 = ASHIFT R1 BY R6;
    I1 = md_shared_scratch_y.;
    DM (32,I1) = R1;
    I2 = @TMP@;
    R0 = DM (8,I2);
    DM (0x1C,I0) = R0;
/* ---- 1. position: x:$a0+k whole part, y:$a0+k coefficient address ---------- */
    R1 = DM (0x11,I0);
    R1 = FEXT R1 BY 0:24;
    R2 = DM (9,I2);
    R3 = -22;
    R4 = 0xFFFFFFFC;
    R5 = 0x147400;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0xA0)(NW);
    I3 = md_shared_scratch_y.;
    I3=MODIFY (I3,0xA0)(NW);
    LCNTR = 0x20 , DO (PC,.L_pos_end)UNTIL LCE;
    R0 = LSHIFT R1 BY -24;
    DM (I1,M6) = R0;
    R6 = LSHIFT R1 BY 8;
    R6 = ASHIFT R6 BY R3;
    R6 = R6 AND R4;
    R6 = R6 + R5;
.L_pos_end:
    R1 = R1 + R2 , DM (I3,M6) = R6;
    I1 = md_shared_scratch_x.;
    R0 = LSHIFT R1 BY -24;
    DM (0xFE,I1) = R0;
    R6 = DM (0x10,I0);
    DM (0xFF,I1) = R6;
    R0 = R0 + R6;                        /* whole part + Y10 */
    R7 = FEXT R1 BY 0:24;                /* frac */
    R6 = DM (8,I2);
    COMP (R0,R6);
    IF LT JUMP .L_pos_keep;
    R0 = DM (0x13,I0);
    R7 = 0;
.L_pos_keep:
    R8 = -8;
    R0 = LSHIFT R0 BY 8;
    R0 = ASHIFT R0 BY R8;
    DM (0x10,I0) = R0;
    R7 = LSHIFT R7 BY 8;
    R7 = ASHIFT R7 BY R8;
    DM (0x11,I0) = R7;
/* ---- 2. loop point -------------------------------------------------------- */
    R5 = DM (10,I2);
    R5 = PASS R5;
    IF NE JUMP .L_lp1;
    R0 = DM (15,I2);
    R0 = MIN(R0,R14);
    DM (0x1E,I0) = R0;
    JUMP .L_lp_done;
.L_lp1:
    R0 = 1;
    COMP (R5,R0);
    IF EQ JUMP .L_lp_done;
    R0 = DM (0x1F,I0);
    R1 = 1;
    R0 = R0 + R1;
    R0 = MIN(R0,R14);
    DM (0x1F,I0) = R0;
    R0 = 0;
    DM (0xC0,I1) = R0;
    DM (0x1E,I0) = R0;
    R8 = DM (12,I2);
    DM (0x10,I0) = R8;
    DM (0xFF,I1) = R8;
    R0 = DM (11,I2);
    R0 = PASS R0;
    IF EQ JUMP .L_lp_zero;
    R1 = 0xBF;
    R1 = R1 - R0;
    R1 = LSHIFT R1 BY 2;
    R2 = I1;
    R1 = R1 + R2;
    I3 = R1;
    LCNTR = R0 , DO (PC,.L_rb_end)UNTIL LCE;
    R1 = DM (I3,M5);
    R1 = R1 - R8;
    R1 = MIN(R1,R14);
    R1 = MAX(R1,R15);
.L_rb_end:
    DM (I3,M6) = R1;
.L_lp_zero:
    /* Ya < $20: the first $20 - cnt offsets restart at 0, Y1e = cnt */
    R0 = DM (0xA,I0);
    R1 = 0x20;
    COMP (R0,R1);
    IF GE JUMP .L_lp_done;
    R0 = DM (11,I2);
    DM (0x1E,I0) = R0;
    R1 = R1 - R0;
    I3 = md_shared_scratch_x.;
    I3=MODIFY (I3,0xA0)(NW);
    R0 = 0;
    LCNTR = R1 , DO (PC,.L_lz_end)UNTIL LCE;
    NOP;
    NOP;
.L_lz_end:
    DM (I3,M6) = R0;
.L_lp_done:
/* ---- 3. unpack 68 words into x:0..$87 --------------------------------------- */
    R0 = DM (14,I2);
    R0 = LSHIFT R0 BY 2;
    R1 = @SRC@;
    R0 = R0 + R1;
    I3 = R0;
    R8 = -8;
    I5 = md_shared_scratch_x.;
    R0 = DM (13,I2);
    BTST R0 BY 0;
    IF SZ JUMP .L_upx_even;
    R0 = DM (I3,M6);
    R1 = LSHIFT R0 BY 8;
    R1 = ASHIFT R1 BY R8;
    DM (0x87,I5) = R1;
    R2 = LSHIFT R0 BY 20;
    R2 = ASHIFT R2 BY R8;
    DM (I5,M6) = R2;
    R3 = 67;
    JUMP .L_upx_go;
.L_upx_even:
    R3 = 68;
.L_upx_go:
    LCNTR = R3 , DO (PC,.L_upx_end)UNTIL LCE;
    R0 = DM (I3,M6);
    R1 = LSHIFT R0 BY 8;
    R1 = ASHIFT R1 BY R8;
    DM (I5,M6) = R1;
    R2 = LSHIFT R0 BY 20;
    R2 = ASHIFT R2 BY R8;
.L_upx_end:
    DM (I5,M6) = R2;
/* ---- second stream into y:0..$87 (position below Y23), crossfade into x:k */
    R0 = DM (16,I2);
    R0 = PASS R0;
    IF EQ JUMP .L_xf;
    R0 = DM (17,I2);
    R0 = LSHIFT R0 BY 2;
    R1 = @SRC@;
    R0 = R0 + R1;
    I3 = R0;
    R8 = -8;
    I5 = md_shared_scratch_y.;
    R0 = DM (13,I2);
    BTST R0 BY 0;
    IF SZ JUMP .L_upy_even;
    R0 = DM (I3,M6);
    R1 = LSHIFT R0 BY 8;
    R1 = ASHIFT R1 BY R8;
    DM (0x87,I5) = R1;
    R2 = LSHIFT R0 BY 20;
    R2 = ASHIFT R2 BY R8;
    DM (I5,M6) = R2;
    R3 = 67;
    JUMP .L_upy_go;
.L_upy_even:
    R3 = 68;
.L_upy_go:
    LCNTR = R3 , DO (PC,.L_upy_end)UNTIL LCE;
    R0 = DM (I3,M6);
    R1 = LSHIFT R0 BY 8;
    R1 = ASHIFT R1 BY R8;
    DM (I5,M6) = R1;
    R2 = LSHIFT R0 BY 20;
    R2 = ASHIFT R2 BY R8;
.L_upy_end:
    DM (I5,M6) = R2;
.L_xf:
    R2 = DM (0xB,I0);                   /* Yb */
    R3 = 0x7FFFFF;
    R3 = R3 - R2;
    R3 = MIN(R3,R14);
    R3 = MAX(R3,R15);
    R2 = LSHIFT R2 BY 8;
    R3 = LSHIFT R3 BY 8;
    I1 = md_shared_scratch_x.;
    I3 = md_shared_scratch_y.;
    R0 = DM (16,I2);
    R0 = PASS R0;
    IF EQ JUMP .L_xf_one;
    LCNTR = 0x88 , DO (PC,.L_xf_end)UNTIL LCE;
    R0 = DM (I1,M5);
    R1 = DM (I3,M6);
    MRF = R2 * R0 (SSF);
    MRF = MRF + R3 * R1 (SSF);
    R4 = MR1F;
    R4 = MIN(R4,R14);
    R4 = MAX(R4,R15);
.L_xf_end:
    DM (I1,M6) = R4;
    JUMP .L_xf_done;
.L_xf_one:
    LCNTR = 0x88 , DO (PC,.L_xf1_end)UNTIL LCE;
    R0 = DM (I1,M5);
    R4 = R2 * R0 (SSF);
    R4 = MIN(R4,R14);
    R4 = MAX(R4,R15);
.L_xf1_end:
    DM (I1,M6) = R4;
.L_xf_done:
    I2 = @TMP@;
/* ---- 4. envelope y:k ---------------------------------------------------- */
    R1 = DM (0x15,I0);
    R2 = DM (3,I0);
    R2 = LSHIFT R2 BY 8;
    I1 = md_shared_scratch_y.;
    LCNTR = 0x20 , DO (PC,.L_env_end)UNTIL LCE;
    DM (I1,M6) = R1;
    R1 = R1 * R2 (SSF);
.L_env_end:
    R1 = MIN(R1,R14);
    DM (0x15,I0) = R1;

/* ---- 5. interpolation: x:$c8+k = lim(2*lim(sum 2*x(r3+j)*c(j))*env(k)) ----- */
    R10 = md_shared_scratch_x.;
    R11 = @SRC@;
    R12 = I0;                            /* I0 is the coefficient pointer here */
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0xA1)(NW);
    I2 = md_shared_scratch_y.;
    I2=MODIFY (I2,0xA0)(NW);
    I5 = md_shared_scratch_y.;
    I4 = md_shared_scratch_x.;
    I4=MODIFY (I4,0xC8)(NW);
    R0 = 0;                              /* r3 = 0 for the first sample */
    R9 = 0xFD;
    R13 = 0x200000;
    LCNTR = 0x20 , DO (PC,.L_int_end)UNTIL LCE;
    R0 = FEXT R0 BY 0:24;
    R4 = LSHIFT R0 BY 2;
    R4 = R4 + R10;
    I3 = R4;
    R1 = DM (I2,M6);
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R11;
    I0 = R1;
    COMPU (R0,R9);
    IF GE JUMP .L_int_slow;
    R2 = DM (I3,M6);
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = R3 * R2 (SSF);
    R2 = DM (I3,M6);
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = MRF + R3 * R2 (SSF);
    R2 = DM (I3,M6);
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = MRF + R3 * R2 (SSF);
    R2 = DM (I3,M6);
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = MRF + R3 * R2 (SSF);
    JUMP .L_int_mr;
.L_int_slow:
    /* (inlined .L_taps) */
    R6 = FEXT R0 BY 0:24;
    R2 = 0;
    COMPU (R6,R13);
    IF GE JUMP .L_tap0_got_i2;
    R5 = 0x100;
    COMPU (R6,R5);
    R6 = LSHIFT R6 BY 2;
    IF LT R6 = R6 + R10;
    IF GE R6 = R6 + R11;
    I3 = R6;
    R2 = DM (0,I3);
    R2 = LSHIFT R2 BY 8;
    R5 = -8;
    R2 = ASHIFT R2 BY R5;
.L_tap0_got_i2:
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = R3 * R2 (SSF);
    R5 = 1;
    R0 = R0 + R5;
    R6 = FEXT R0 BY 0:24;
    R2 = 0;
    COMPU (R6,R13);
    IF GE JUMP .L_tap1_got_i2;
    R5 = 0x100;
    COMPU (R6,R5);
    R6 = LSHIFT R6 BY 2;
    IF LT R6 = R6 + R10;
    IF GE R6 = R6 + R11;
    I3 = R6;
    R2 = DM (0,I3);
    R2 = LSHIFT R2 BY 8;
    R5 = -8;
    R2 = ASHIFT R2 BY R5;
.L_tap1_got_i2:
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = MRF + R3 * R2 (SSF);
    R5 = 1;
    R0 = R0 + R5;
    R6 = FEXT R0 BY 0:24;
    R2 = 0;
    COMPU (R6,R13);
    IF GE JUMP .L_tap2_got_i2;
    R5 = 0x100;
    COMPU (R6,R5);
    R6 = LSHIFT R6 BY 2;
    IF LT R6 = R6 + R10;
    IF GE R6 = R6 + R11;
    I3 = R6;
    R2 = DM (0,I3);
    R2 = LSHIFT R2 BY 8;
    R5 = -8;
    R2 = ASHIFT R2 BY R5;
.L_tap2_got_i2:
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = MRF + R3 * R2 (SSF);
    R5 = 1;
    R0 = R0 + R5;
    R6 = FEXT R0 BY 0:24;
    R2 = 0;
    COMPU (R6,R13);
    IF GE JUMP .L_tap3_got_i2;
    R5 = 0x100;
    COMPU (R6,R5);
    R6 = LSHIFT R6 BY 2;
    IF LT R6 = R6 + R10;
    IF GE R6 = R6 + R11;
    I3 = R6;
    R2 = DM (0,I3);
    R2 = LSHIFT R2 BY 8;
    R5 = -8;
    R2 = ASHIFT R2 BY R5;
.L_tap3_got_i2:
    R3 = DM (I0,M6);
    R3 = LSHIFT R3 BY 8;
    MRF = MRF + R3 * R2 (SSF);
    JUMP .L_taps_ret_i2;
.L_taps_ret_i2:
.L_int_mr:
    R2 = MR1F;
    R2 = MIN(R2,R14);
    R2 = MAX(R2,R15);
    R3 = DM (I5,M6);
    R3 = LSHIFT R3 BY 8;
    R2 = R2 * R3 (SSF);
    R2 = MIN(R2,R14);
    DM (I4,M6) = R2;
.L_int_end:
    R0 = DM (I1,M6);                     /* r3 of the next sample */
    I0 = R12;

/* ---- 6. biquad: acc += 2c2 w(n-2) + 4g2c w(n-1) + 2b0 x(n-2) + 2b1 x(n-1)
 * + 2b0 x(n); w(n) = l: store of acc. Registers (even sample): w(n-2) R4,
 * w(n-1) R5, x(n-2) R6, x(n-1) R7; R10..R13 = c2, g2c, b0, b1 << 8 ------- */
    I2 = @TMP@;
    R10 = DM (0,I2);
    R10 = LSHIFT R10 BY 8;
    R11 = DM (1,I2);
    R11 = LSHIFT R11 BY 8;
    R12 = DM (2,I2);
    R12 = LSHIFT R12 BY 8;
    R13 = DM (3,I2);
    R13 = LSHIFT R13 BY 8;
    I3 = md_shared_scratch_y.;
    I3=MODIFY (I3,0x78)(NW);
    R0 = DM (0,I2);
    DM (0,I3) = R0;
    R0 = DM (1,I2);
    DM (1,I3) = R0;
    R0 = DM (2,I2);
    DM (2,I3) = R0;
    R0 = DM (3,I2);
    DM (3,I3) = R0;
    R0 = DM (2,I2);
    DM (4,I3) = R0;
    I1 = md_shared_scratch_x.;
    R4 = DM (0x17,I0);
    R5 = DM (0x18,I0);
    R6 = DM (0x1A,I0);
    R7 = DM (0x19,I0);
    DM (0xC4,I1) = R4;
    DM (0xC5,I1) = R5;
    R0 = DM (0xE6,I1);
    DM (0x1A,I0) = R0;
    R0 = DM (0xE7,I1);
    DM (0x19,I0) = R0;
    R0 = DM (0x1B,I0);
    R0 = LSHIFT R0 BY 8;
    MR1F = R5;
    MR0F = R0;
    R8 = -8;
    I3 = md_shared_scratch_x.;
    I3=MODIFY (I3,0xC8)(NW);
    I4 = md_shared_scratch_x.;
    I4=MODIFY (I4,0xC6)(NW);
    I5 = md_shared_scratch_y.;
    I5=MODIFY (I5,0xC6)(NW);
    I2 = I0;
    I2=MODIFY (I2,0x25)(NW);
    LCNTR = 0x10 , DO (PC,.L_bq_end)UNTIL LCE;
    R0 = DM (I3,M6);
    MRF = MRF + R10 * R4 (SSF);
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R11 * R5 (SSF);       /* 4g2c (2g2c each) */
    MRF = MRF + R12 * R6 (SSF);
    MRF = MRF + R13 * R7 (SSF);
    MRF = MRF + R12 * R0 (SSF);
    R6 = PASS R0;
    R1 = MR1F;
    R9 = MR0F;
    R9 = ASHIFT R9 BY R8;
    R4 = MIN(R1,R14);
    R4 = MAX(R4,R15);
    COMP (R4,R1);
    IF NE R9 = LSHIFT R1 BY -31;
    IF NE R9 = R9 - 1;
    DM (I4,M6) = R4;
    DM (I2,M6) = R4;
    DM (I5,M6) = R9;
    R0 = DM (I3,M6);
    MRF = MRF + R10 * R5 (SSF);
    MRF = MRF + R11 * R4 (SSF);
    MRF = MRF + R11 * R4 (SSF);       /* 4g2c (2g2c each) */
    MRF = MRF + R12 * R7 (SSF);
    MRF = MRF + R13 * R6 (SSF);
    MRF = MRF + R12 * R0 (SSF);
    R7 = PASS R0;
    R1 = MR1F;
    R9 = MR0F;
    R9 = ASHIFT R9 BY R8;
    R5 = MIN(R1,R14);
    R5 = MAX(R5,R15);
    COMP (R5,R1);
    IF NE R9 = LSHIFT R1 BY -31;
    IF NE R9 = R9 - 1;
    DM (I4,M6) = R5;
    DM (I2,M6) = R5;
.L_bq_end:
    DM (I5,M6) = R9;
    I1 = md_shared_scratch_x.;
    I3 = md_shared_scratch_y.;
    R0 = DM (0xE4,I1);
    DM (0x17,I0) = R0;
    R0 = DM (0xE5,I1);
    DM (0x18,I0) = R0;
    R0 = DM (0xE5,I3);
    DM (0x1B,I0) = R0;
    I1 = md_shared_scratch_y.;
    R0 = DM (32,I1);
    R0 = FEXT R0 BY 0:24;
    I1 = md_shared_y20.;
    DM (0,I1) = R0;
    JUMP .L_exit;

    /* taps of an offset R0 outside 0..$fc: x:(R0 + j) as a parallel-move read
     * (scratch, source words, 0 at and above $200000; the guard keeps them off
     * boot X); MRF = sum 2 * x * coefficient (I0) */
.L_decline:
    /* tail call: the C reference render runs in this render's place, in
     * its caller's frame (not nested under this one: the audio stack is
     * 509 words) */
    R4 = I0;
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I7=MODIFY (I7,0x34)(NW);
    JUMP e12sd_render_block_44k1_c.;
.L_exit:
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I12=DM (M7,I6);
    JUMP (M14,I12) (DB);
    RFRAME;
    NOP;
.ENDSEG;
